import os,json,subprocess,stat
from pathlib import Path
base=Path("/root/.pm2")
out={"old_home":{},"dumps":{},"history":{},"open_handles":0,"private_services":{},"infra_root":{}}
out["old_home"]={"real":base.is_dir() and not base.is_symlink(),"files_count":sum(1 for p in base.rglob("*") if p.is_file()) if base.is_dir() else 0}
for name in ("dump.pm2","dump.pm2.bak"):
 p=base/name
 if p.is_file():
  try:
   x=json.loads(p.read_text())
   out["dumps"][name]={"valid_json":True,"names":[z.get("name") for z in x if isinstance(z,dict)],"bytes":p.stat().st_size,"owner":p.stat().st_uid}
  except Exception:out["dumps"][name]={"valid_json":False,"bytes":p.stat().st_size}
if (base/"logs").is_dir():
 for p in sorted((base/"logs").iterdir()):
  try:out["history"][p.name]={"bytes":p.stat().st_size,"owner":p.stat().st_uid}
  except OSError:pass
for proc in Path("/proc").iterdir():
 if not proc.name.isdecimal() or int(proc.name) in (os.getpid(),os.getppid()):continue
 try:
  for fd in (proc/"fd").iterdir():
   try:
    l=os.readlink(str(fd))
    if l==str(base) or l.startswith(str(base)+"/"):out["open_handles"]+=1
   except OSError:pass
 except OSError:pass
for n in ("pm2-root","pm2-telegram-robot-leads","pm2-iptvpn-bot"):
 a=subprocess.run(["systemctl","show",n,"-p","ActiveState,UnitFileState,MainPID"],capture_output=True,text=True,timeout=7)
 out["private_services"][n]=dict(line.split("=",1) for line in a.stdout.splitlines() if "=" in line)
root=Path("/srv/projects/VPS")
out["infra_root"]={"already_exists":root.exists() or root.is_symlink(),"parent_real":root.parent.is_dir() and not root.parent.is_symlink()}
print(json.dumps(out,sort_keys=True))
